{"contract":"write","tool":"write","path":"/home/dev/project/src/main_window.py","content":"from PySide6.QtWidgets import QMainWindow, QToolBar
from PySide6.QtCore import QThread, Signal


class _QueueWorker(QThread):
    finished_queuing = Signal(int)

    def __init__(self, books):
        super().__init__()
        self.books = books

    def run(self):
        count = 0
        for book in self.books:
            book.fetch_toc()
            count += 1
        self.finished_queuing.emit(count)


class _AIWorker(QThread):
    done = Signal(str)

    def __init__(self, book, task):
        super().__init__()
        self.book = book
        self.task = task

    def run(self):
        result = self.task(self.book)
        self.done.emit(result)


class MainWindow(QMainWindow):
    def __init__(self, library, readest_client):
        super().__init__()
        self.library = library
        self.readest = readest_client
        self._ai_workers = []
        self._build_toolbar()

    def _build_toolbar(self):
        tb = QToolBar('Main', self)
        self.addToolBar(tb)
        tb.addAction('Add book', self._add_book)
        tb.addAction('AI summarize', self._start_ai_processing)

    def _add_book(self):
        self.library.add_from_dialog(self)

    def _start_ai_processing(self):
        book = self.library.current_book()
        worker = _AIWorker(book, self.library.summarize)
        worker.done.connect(self.statusBar().showMessage)
        self._ai_workers.append(worker)
        worker.start()
"}

