{"contract":"write","tool":"write","path":"/home/dev/project/src/ledger.py","content":"# Local-first ledger store.
import json
from pathlib import Path

DATA_DIR = Path.home() / '.ledger'


def load_entries(name):
    path = DATA_DIR / (name + '.json')
    if not path.exists():
        return []
    return json.loads(path.read_text())


def save_entries(name, entries):
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    (DATA_DIR / (name + '.json')).write_text(json.dumps(entries, indent=2))


def add_entry(name, amount, memo):
    if amount == 0:
        raise ValueError('amount must be non-zero')
    entries = load_entries(name)
    entries.append({'amount': amount, 'memo': memo})
    save_entries(name, entries)
    return entries
"}

