{"contract":"write","tool":"write","path":"/home/dev/project/src/MainApplication.ts","content":"export class MainApplication {
  private canvas = document.createElement("canvas");
  private mode = "play";
  private angle = 0;

  constructor(private root: HTMLElement) {}

  init(): void {
    this.root.appendChild(this.canvas);
    this.draw();
  }

  setMode(mode: string): void {
    this.mode = mode;
  }

  private draw(): void {
    const ctx = this.canvas.getContext("2d")!;
    ctx.clearRect(0, 0, 400, 400);
    ctx.beginPath();
    ctx.arc(200, 200, 150, this.angle, this.angle + Math.PI * 2);
    ctx.stroke();
  }
}
